/**
 * Query is deliberately generous about reading.
 *
 * A citizen must be able to check a title before paying anybody: without an
 * account, without an official's permission, and without anybody knowing they
 * looked. Every read below is public and unauthenticated for that reason — the
 * secrecy that protects a corrupt registry is the same secrecy that stops a
 * buyer discovering the land was already sold.
 */
export interface Query {
  /** Params returns the quorum and challenge window currently in force. */
  Params(request: QueryParamsRequest): Promise<QueryParamsResponse>;
  /** Parcel returns one parcel by its chain id. */
  Parcel(request: QueryParcelRequest): Promise<QueryParcelResponse>;
  /**
   * ParcelByRef finds a parcel by the registry's own reference — the number
   * written on the paper somebody is actually holding.
   *
   * The reference travels in the query string rather than as a path segment,
   * and that is not a style choice. Registry references contain slashes —
   * ACC/GA/2019/00412 is an ordinary one — and a path template binds `{field}`
   * to a single URL segment. A reference with slashes in it therefore matches
   * no route at all, percent-encoded or raw, which made the module's primary
   * lookup the one lookup that could not be performed over REST.
   */
  ParcelByRef(request: QueryParcelByRefRequest): Promise<QueryParcelByRefResponse>;
  /**
   * ParcelByGeometry exposes the uniqueness check, so a surveyor can ask "is
   * this ground already registered" before a second title is ever proposed.
   *
   * In the query string for the same reason as ParcelByRef. The keeper accepts
   * any non-empty string as a survey hash and deliberately does not impose an
   * encoding, so a registry that records its hashes in base64 — an alphabet
   * that includes '/' — would find this route unreachable for exactly the
   * parcels it was asked about. A lookup that works until somebody changes
   * their hash encoding is a lookup nobody can rely on.
   */
  ParcelByGeometry(request: QueryParcelByGeometryRequest): Promise<QueryParcelByGeometryResponse>;
  /** Transfer returns one transfer, including who signed it and when. */
  Transfer(request: QueryTransferRequest): Promise<QueryTransferResponse>;
  /**
   * TransfersByParcel returns every transfer ever proposed for a parcel,
   * including the abandoned and the disputed. This is the history that makes a
   * theft arguable afterwards.
   */
  TransfersByParcel(request: QueryTransfersByParcelRequest): Promise<QueryTransfersByParcelResponse>;
  /**
   * PendingTransfers lists transfers awaiting completion. The public list is
   * what makes the challenge window meaningful: an objection cannot be filed
   * against a transfer nobody can see.
   */
  PendingTransfers(request: QueryPendingTransfersRequest): Promise<QueryPendingTransfersResponse>;
  /** Authorities lists the registry offices governance has admitted. */
  Authorities(request: QueryAuthoritiesRequest): Promise<QueryAuthoritiesResponse>;
  /** ParcelsByHolder lists what one account holds. */
  ParcelsByHolder(request: QueryParcelsByHolderRequest): Promise<QueryParcelsByHolderResponse>;
  /**
   * FractionalisationAuthority returns the registry's standing permission to
   * fractionalise a parcel, and whether it is still live.
   *
   * Public for the same reason every other read here is: somebody being sold a
   * share in a piece of land must be able to check, before paying, that the
   * registry ever permitted the sale and that the permission has not been
   * withdrawn or run out.
   */
  FractionalisationAuthority(
    request: QueryFractionalisationAuthorityRequest,
  ): Promise<QueryFractionalisationAuthorityResponse>;
}

